WFJ.Data.add("gossip", {
  ["dd0652c334ec9204"] = { "È ammirevole ciò che la ⟦The League of Arathor=Lega di Arathor⟧ sta cercando di fare nel ⟦Arathi Basin=Bacino d'Arathi⟧. Peccato che quelle abominazioni non morte e i loro amici dell'⟦Horde=Orda⟧ si mettano di mezzo. Va' al Castello di ⟦Stormwind=Roccavento⟧. lady Hoteshem ti aspetta nella sala delle udienze del re. Può aiutarti a raggiungere il ⟦Arathi Basin=Bacino d'Arathi⟧.", "." },
  ["dd0bcbe1a905db42"] = { "Dov'è l'istruttore di Sartoria?", "." },
  ["dd0ce3c112e6cdc6"] = { "Non puoi sfuggire a un guerriero dell'⟦Horde=Orda⟧! Prendi questo! E questo!", "." },
  ["dd2055d04ede22c1"] = { "Brontola, brontola...", "." },
  ["dd3d89f0b3050cb4"] = { "Salute, {class}. Sono il feldmaresciallo Snowfall, al comando dello sforzo bellico qui. Abbiamo una strada dura davanti, <ragazzo/ragazza>, quindi se puoi dare una mano, fallo. E non esitare a fare domande.", "." },
  ["dd4173271ce6b8f9"] = { "Ehi, Pratt, puoi insegnarmi di nuovo a fare gli ⟦Wild Leather Boots=Stivali di Cuoio Selvatico⟧?", "." },
  ["dd4f0be301b8beba"] = { "10.000 anni di sapere registrato tendono ad attirare all'Athenaeum la gente sbagliata. I libri vengono rubati, recuperati e rubati di nuovo ogni giorno.", "." },
  ["dd559c2394ed047b"] = { "Brutta pellicina", "." },
  ["dd56d7737cf8248e"] = { "Salute, {class}. Nei miei anni ho visto molti tauren desiderosi di dimostrare il proprio valore alla tribù. Non bisogna dimenticare che l'entusiasmo non sostituisce la saggezza e l'esperienza.", "." },
  ["dd654bbddd394193"] = { "{name} ha assaltato la miniera!", "." },
  ["dd6ab14874410ff6"] = { "La tua famiglia ti saluta, Ribbly. E vuole la tua testa!", "." },
  ["dd7333ae2d41e4b8"] = { "Nella morte, gli animali del mondo ci donano sia la vita sia la protezione. Se senti di poter offrire il giusto rispetto per il loro sacrificio, allora la professione di Scuoiatura potrebbe fare per te. Parla con Eladriel sulla Craftsman's Terrace, nel nord di Darnassus, per saperne di più.", "." },
  ["dd745be6a7b3d716"] = { "Distruggi subito l'invasore del Flagello, prima che sia troppo tardi!", "." },
  ["dd7c3475d0199a50"] = { "Remulos, qualcosa mi trascina indietro... Tyrande... dille che la amo... Dille che sono al sicuro. Dille... Dille che tornerò... Addio...", "." },
  ["dd7dd9b8d09c072a"] = { "Non avrei mai pensato che sarebbe arrivato il giorno in cui avrei lasciato la mia terra natale, le ⟦Westfall=Marche Occidentali⟧. . . .", "." },
  ["dd82a5794440a9f9"] = { "Queste grandi bestie conoscono sentieri che a piedi non troveresti: ti ci porteranno in fretta e magari, già che ci sono, ti mostreranno qualcosa di nuovo.", "." },
  ["dd888c77707234cb"] = { "⟦First Aid=Primo Soccorso⟧? Be', a me non sembri <ferito/ferita>. Se t'interessa davvero imparare il ⟦First Aid=Primo Soccorso⟧, ⟦Nissa Firestone=Nissa Pietrardente⟧ è quella da cui imparare. Va' a trovarla vicino alla ⟦Great Forge=Grande Forgia⟧, nella sua bottega, The Ironforge Physician.", "." },
  ["dd9a167b318efb4a"] = { "Coprimi le spalle! Vedo cosa riesco a trovare in tutta questa robaccia...", "." },
  ["dd9ad60117812c36"] = { "Almeno non saremmo in giro a doverlo ripulire.", "." },
  ["dda93b5001b331db"] = { "Cercalo in alto, sul lato ovest della ⟦Valley of Strength=Valle della Forza⟧. Ti fanno entrare solo se sei un ufficiale! Altrimenti parla con il sergente Ba'sha, qui fuori.", "." },
  ["ddaaea28a07399c6"] = { "Vuoi addestrarti con Borgus? Sì, posso dirti dove trovarlo. Attraversa la piazza a nord-ovest della mia forgia, poi prendi la strada a ovest. Lo troverai nel secondo edificio sulla destra.", "." },
  ["ddb9d4eda71d319a"] = { "Chi controlla il ⟦Snowfall Graveyard=Cimitero di Nevealta⟧?", "." },
  ["ddc9d9bd6a1984fb"] = { "PER MAGNI!", "." },
  ["ddceaa4afea9b1ea"] = { "%s aggiunge la foschia ai germogli di Petalorosso.", "." },
  ["ddd4983e2faf7796"] = { "Salve, {class}. Sono l'alto inventore Mekkatorque, degli esuli di Gnomeregan.", "." },
  ["ddda4cdf2de7edfd"] = { "La locanda in fiamme.", "." },
  ["dde4b97b977bfc65"] = { "Benvenuti al grande spettacolo, amici. Fatevi avanti a morire!", "." },
  ["ddeb4c2955e25171"] = { "Salute, amico mio, e benvenut<o/a> al più grande spettacolo di Azeroth!\n\nSu, fatti avanti e goditi tutto ciò che abbiamo da offrire. Lasciati stupire dalle meraviglie che la ⟦Darkmoon Faire=Fiera di Lunacupa⟧ ha scovato in questo mondo vasto e misterioso! Non abbiamo badato a spese per offrirti un divertimento che delizierà bambini di tutte le età!", "." },
  ["ddf0467b62f3b682"] = { "Se sei qui, significa che ti senti in grado di cominciare lo studio dell'evocazione di compagni demoniaci al tuo servizio. Partiremo dalle creature più infime che sarai in grado di richiamare e proseguiremo da lì. Cominciamo.", "." },
  ["ddf159a8c65a49fc"] = { "Pare che la Luce ci abbia abbandonati.", "." },
})
